    if(c.medias)[['s100',COL.m100],['s50',COL.m50],['s20',COL.m20]].forEach(([k,col])=>s+=`<path d="${camino(x[k],ini,fin,X,Y)}" fill="none" stroke="${col}" stroke-width="1.5"${k==='s100'?' stroke-dasharray="9 3"':''}/>`);
