    let ys=nv.map(n=>({n,y:Y(n.v)})).sort((a,b)=>a.y-b.y);for(let i=1;i<ys.length;i++)if(ys[i].y-ys[i-1].y<15)ys[i].y=ys[i-1].y+15;
    for(const{n,y}of ys){const t=n.k+' '+fmt(n.v,1),w=t.length*6.1+8;s+=`<rect x="${(cx.W-cx.R-w-3).toFixed(1)}" y="${(y-8).toFixed(1)}" width="${w.toFixed(1)}" height="15" rx="3" fill="#fff" stroke="${COL.neu}"/><text x="${(cx.W-cx.R-w/2-3).toFixed(1)}" y="${(y+3.3).toFixed(1)}" text-anchor="middle" class="nl">${t}</text>`}
